// Generates one C# enum per TweakDB record group (server/Managed/TweakDb/Generated/<Group>.cs, e.g. Character.Panam with
// the record id as its value) plus their implicit conversions to TweakDbId, from WolvenKit's tweakdbstr.kark.
// Run by hand (never in CI, it needs the game's proprietary Oodle DLL), then commit the generated files:
//
//   dotnet run server/Tools/GenerateTweakDb.cs -- "<game install path>" [--kark <local tweakdbstr.kark>]
//
// By default the name list is downloaded from WolvenKit, pinned to WolvenKitCommit. --kark reads a local file instead,
// e.g. <game>/bin/x64/plugins/cyber_engine_tweaks/tweakdb/tweakdbstr.kark of a CET install.
#:property AllowUnsafeBlocks=true
#:property PublishAot=false

using System.Runtime.InteropServices;
using System.Text;

const string WolvenKitCommit = "95074158ed971aea39fc8abc50c2574381f4aad2";
string[] groups = ["Character", "Vehicle"];

var karkUrl = $"https://raw.githubusercontent.com/WolvenKit/WolvenKit/{WolvenKitCommit}/WolvenKit.Common/Resources/tweakdbstr.kark";

string? gamePath = null;
string? karkPath = null;
for (var i = 0; i < args.Length; i++)
{
    if (args[i] == "--kark")
    {
        if (++i >= args.Length) return Tool.Fail("--kark needs a path");
        karkPath = args[i];
    }
    else if (gamePath == null) gamePath = args[i];
    else return Tool.Fail($"Unexpected argument '{args[i]}'");
}

if (gamePath == null)
    return Tool.Fail("Usage: dotnet run server/Tools/GenerateTweakDb.cs -- \"<game install path>\" [--kark <tweakdbstr.kark>]");

var repoRoot = Tool.FindRepoRoot();
if (repoRoot == null)
    return Tool.Fail("Could not find the repo root (server/Managed/Cyberverse.Server.csproj) above the current directory");

var oodlePath = Path.Combine(gamePath, "bin", "x64", "oo2ext_7_win64.dll");
if (!File.Exists(oodlePath)) return Tool.Fail($"Oodle DLL not found: {oodlePath}");

byte[] kark;
if (karkPath != null)
{
    kark = File.ReadAllBytes(karkPath);
}
else
{
    Console.WriteLine($"Downloading {karkUrl}");
    using var http = new HttpClient();
    kark = await http.GetByteArrayAsync(karkUrl);
}

var records = Tool.ReadRecords(Tool.Decompress(kark, oodlePath));
Console.WriteLine($"Read {records.Count} records from {(karkPath ?? "WolvenKit " + WolvenKitCommit)}");

var outDir = Path.Combine(repoRoot, "server", "Managed", "TweakDb", "Generated");
Directory.CreateDirectory(outDir);
var header = "// <auto-generated/>\n" +
             $"// Generated by server/Tools/GenerateTweakDb.cs from WolvenKit {WolvenKitCommit} tweakdbstr.kark. Don't edit; rerun the tool instead.\n";

foreach (var group in groups)
{
    var prefix = group + ".";
    var names = new List<string>();
    var skipped = new List<string>();
    foreach (var name in records)
    {
        if (!name.StartsWith(prefix, StringComparison.Ordinal)) continue;
        var member = name.Substring(prefix.Length);
        if (member.Length == 0 || member.Contains('.') || name.Contains("_inline", StringComparison.Ordinal)) continue;
        // The record name is rebuilt from the enum member (nameof(Character) + "." + member), so only names that are
        // C# identifiers as they are can be generated.
        if (name.Length > 255 || !Tool.IsIdentifier(member)) { skipped.Add(name); continue; }
        names.Add(name);
    }
    names.Sort(StringComparer.Ordinal);

    var sb = new StringBuilder(header);
    sb.Append("namespace Cyberverse.Server.TweakDb.Generated;\n\n");
    sb.Append($"public enum {group} : ulong\n{{\n");

    var ids = new Dictionary<ulong, string>();
    var escaped = 0;
    foreach (var name in names.Distinct(StringComparer.Ordinal))
    {
        var id = Tool.Id(name);
        if (ids.TryGetValue(id, out var other))
            return Tool.Fail($"{other} and {name} have the same record id 0x{id:X16}, which would make them one enum value");
        ids[id] = name;

        var member = name.Substring(prefix.Length);
        if (Tool.Keywords.Contains(member))
        {
            member = "@" + member; // @ doesn't change the member's name, so the record name still comes back intact
            escaped++;
        }
        sb.Append($"    {member} = 0x{id:X16}UL,\n");
    }
    sb.Append("}\n");

    var file = Path.Combine(outDir, group + ".cs");
    File.WriteAllBytes(file, new UTF8Encoding(false).GetBytes(sb.ToString()));
    Console.WriteLine($"{group}: {ids.Count} records, {escaped} escaped keywords, {skipped.Count} skipped -> {file}");
    foreach (var s in skipped) Console.WriteLine($"  skipped: {s}");
}

// One implicit conversion per group, so every group's enum can be passed where a TweakDbId is expected.
var conversions = new StringBuilder(header);
conversions.Append("using Cyberverse.Server.TweakDb.Generated;\n\nnamespace Cyberverse.Server.TweakDb;\n\n");
conversions.Append("public readonly partial record struct TweakDbId\n{\n");
foreach (var group in groups)
{
    conversions.Append($"    public static implicit operator TweakDbId({group} record) => new((ulong)record);\n");
}
conversions.Append("}\n");
var conversionsFile = Path.Combine(outDir, "TweakDbId.Conversions.cs");
File.WriteAllBytes(conversionsFile, new UTF8Encoding(false).GetBytes(conversions.ToString()));
Console.WriteLine($"Conversions for {groups.Length} groups -> {conversionsFile}");
return 0;

static unsafe class Tool
{
    public static readonly HashSet<string> Keywords = new(StringComparer.Ordinal)
    {
        "abstract", "as", "base", "bool", "break", "byte", "case", "catch", "char", "checked", "class", "const",
        "continue", "decimal", "default", "delegate", "do", "double", "else", "enum", "event", "explicit", "extern",
        "false", "finally", "fixed", "float", "for", "foreach", "goto", "if", "implicit", "in", "int", "interface",
        "internal", "is", "lock", "long", "namespace", "new", "null", "object", "operator", "out", "override",
        "params", "private", "protected", "public", "readonly", "ref", "return", "sbyte", "sealed", "short",
        "sizeof", "stackalloc", "static", "string", "struct", "switch", "this", "throw", "true", "try", "typeof",
        "uint", "ulong", "unchecked", "unsafe", "ushort", "using", "virtual", "void", "volatile", "while",
    };

    public static int Fail(string message)
    {
        Console.Error.WriteLine(message);
        return 1;
    }

    public static string? FindRepoRoot()
    {
        var dir = new DirectoryInfo(Directory.GetCurrentDirectory());
        while (dir != null)
        {
            if (File.Exists(Path.Combine(dir.FullName, "server", "Managed", "Cyberverse.Server.csproj")))
                return dir.FullName;
            dir = dir.Parent;
        }
        return null;
    }

    // Same as RecordIdUtils.ToRecordId: (length << 32) | IEEE CRC-32 of the (ASCII) name
    public static ulong Id(string name)
    {
        var crc = 0xFFFFFFFFu;
        foreach (var c in name)
        {
            crc ^= (byte)c;
            for (var k = 0; k < 8; k++) crc = (crc & 1) != 0 ? (crc >> 1) ^ 0xEDB88320u : crc >> 1;
        }
        return ((ulong)name.Length << 32) | ~crc;
    }

    public static bool IsIdentifier(string member) =>
        !char.IsAsciiDigit(member[0]) && member.All(c => char.IsAsciiLetterOrDigit(c) || c == '_');

    public static byte[] Decompress(byte[] kark, string oodlePath)
    {
        if (kark.Length < 8 || kark[0] != 'K' || kark[1] != 'A' || kark[2] != 'R' || kark[3] != 'K')
            throw new InvalidDataException("Not a KARK file (bad magic)");
        var rawSize = BitConverter.ToUInt32(kark, 4);
        var raw = new byte[rawSize];
        var lib = NativeLibrary.Load(oodlePath);
        var fn = (delegate* unmanaged[Cdecl]<byte*, long, byte*, long, int, int, int, void*, long, void*, void*, void*, long, int, long>)
            NativeLibrary.GetExport(lib, "OodleLZ_Decompress");
        long got;
        fixed (byte* comp = &kark[8])
        fixed (byte* dst = raw)
            got = fn(comp, kark.Length - 8, dst, rawSize, 1, 0, 0, null, 0, null, null, null, 0, 3);
        if (got != rawSize) throw new InvalidDataException($"Oodle decompressed {got} bytes, expected {rawSize}");
        return raw;
    }

    public static List<string> ReadRecords(byte[] raw)
    {
        var pos = 0;
        if (raw.Length < 20) throw new InvalidDataException("Decompressed data too short");
        int ReadInt()
        {
            var v = BitConverter.ToInt32(raw, pos);
            pos += 4;
            return v;
        }

        var magic = (uint)ReadInt();
        if (magic != 0x0BB1DB57) throw new InvalidDataException($"Bad tweakdbstr magic 0x{magic:X8}");
        var version = ReadInt();
        if (version != 1) throw new InvalidDataException($"Unsupported tweakdbstr version {version}");
        int recordCount = ReadInt(), flatCount = ReadInt(), queryCount = ReadInt();

        string ReadString()
        {
            var b = raw[pos++];
            var negative = (b & 0x80) != 0;
            var more = (b & 0x40) != 0;
            long length = b & 0x3F;
            var shift = 6;
            while (more)
            {
                b = raw[pos++];
                length |= (long)(b & 0x7F) << shift;
                shift += 7;
                more = (b & 0x80) != 0;
            }
            var size = negative ? length : length * 2;
            if (pos + size > raw.Length) throw new InvalidDataException("String runs past the end of the data");
            var s = negative ? Encoding.Latin1.GetString(raw, pos, (int)size) : Encoding.Unicode.GetString(raw, pos, (int)size);
            pos += (int)size;
            return s;
        }

        var records = new List<string>(recordCount);
        for (var i = 0; i < recordCount; i++) records.Add(ReadString());
        for (var i = 0; i < flatCount + queryCount; i++) ReadString();
        if (pos != raw.Length) throw new InvalidDataException($"{raw.Length - pos} bytes left over after reading all strings");
        return records;
    }
}
